CREATE TABLE orders(id INTEGER PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,creation_nonce TEXT NOT NULL UNIQUE,user_id INTEGER NOT NULL REFERENCES users(id),status TEXT NOT NULL CHECK(status IN('AWAITING_PAYMENT','CONFIRMED','PREPARING','SHIPPED','DELIVERED')),payment_status TEXT NOT NULL CHECK(payment_status IN('REJECTED','APPROVED')),currency TEXT NOT NULL DEFAULT 'PEN' CHECK(currency='PEN'),subtotal_cents INTEGER NOT NULL CHECK(subtotal_cents BETWEEN 1 AND 990000000000),total_cents INTEGER NOT NULL CHECK(total_cents=subtotal_cents),recipient_snapshot TEXT NOT NULL,phone_snapshot TEXT NOT NULL,region_snapshot TEXT NOT NULL,province_snapshot TEXT NOT NULL,district_snapshot TEXT NOT NULL,street_snapshot TEXT NOT NULL,reference_snapshot TEXT,source_cart_id INTEGER REFERENCES carts(id),source_cart_version INTEGER,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE order_items(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),product_id INTEGER NOT NULL REFERENCES products(id),sku_snapshot TEXT NOT NULL,name_snapshot TEXT NOT NULL,unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents BETWEEN 1 AND 100000000),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 99),line_total_cents INTEGER NOT NULL CHECK(line_total_cents=unit_price_cents*quantity),promotion_snapshot TEXT,UNIQUE(order_id,product_id));
CREATE TABLE simulated_payments(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),outcome TEXT NOT NULL CHECK(outcome IN('APPROVED','REJECTED')),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),currency TEXT NOT NULL CHECK(currency='PEN'),created_at TEXT NOT NULL);
CREATE UNIQUE INDEX one_approval ON simulated_payments(order_id) WHERE outcome='APPROVED';
CREATE TABLE inventory_movements(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES products(id),order_id INTEGER REFERENCES orders(id),actor_user_id INTEGER REFERENCES users(id),kind TEXT NOT NULL CHECK(kind IN('SEED','ADJUSTMENT','SALE')),delta INTEGER NOT NULL,quantity_after INTEGER NOT NULL CHECK(quantity_after BETWEEN 0 AND 1000000),reason TEXT NOT NULL,created_at TEXT NOT NULL,CHECK(kind!='SALE' OR (delta<0 AND order_id IS NOT NULL)));
CREATE UNIQUE INDEX one_sale ON inventory_movements(order_id,product_id) WHERE kind='SALE';
CREATE TABLE order_status_history(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),from_status TEXT,to_status TEXT NOT NULL,actor_user_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE idempotency_records(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),operation TEXT NOT NULL,key TEXT NOT NULL,request_hash TEXT NOT NULL,response_status INTEGER NOT NULL,response_json TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(user_id,operation,key));
CREATE INDEX orders_customer ON orders(user_id,created_at);
CREATE INDEX payments_order ON simulated_payments(order_id,created_at);
CREATE INDEX history_order ON order_status_history(order_id,created_at);
